/* ===================================================================
   PTCAD: Toast แบบเบาๆ (สไตล์ Shopee) แทน popup กลางจอเดิม
   + ปุ่ม "ซื้อเลย" ที่ยิง add-to-cart แล้วพาไปหน้าตะกร้าทันที
=================================================================== */
function ptShowCartToast(productName){
    var old = document.getElementById('pt-cart-toast');
    if (old) old.remove();

    var toast = document.createElement('div');
    toast.id = 'pt-cart-toast';
    toast.style.cssText = 'position:fixed;top:90px;right:20px;z-index:99999;'
        + 'background:#fff;border-radius:14px;box-shadow:0 12px 34px rgba(20,53,143,.18);'
        + 'padding:14px 18px;display:flex;align-items:center;gap:10px;'
        + 'font-family:Poppins,"Noto Sans Thai",sans-serif;font-size:14px;color:#0b1f4d;'
        + 'transform:translateX(120%);transition:transform .3s ease;max-width:320px;';
    toast.innerHTML = '<span style="width:26px;height:26px;border-radius:50%;background:#20b26b;'
        + 'color:#fff;display:flex;align-items:center;justify-content:center;flex:none;font-size:14px;">&#10003;</span>'
        + '<span>เพิ่ม <b>' + productName + '</b> ลงตะกร้าแล้ว</span>';

    document.body.appendChild(toast);
    requestAnimationFrame(function(){ toast.style.transform = 'translateX(0)'; });

    // เด้งไอคอนตะกร้าบนหัวเว็บให้เห็นว่ามีของเข้า
    var cartBadge = document.querySelector('.cart_show_quantity');
    if (cartBadge) {
        cartBadge.style.transition = 'transform .25s ease';
        cartBadge.style.transform = 'scale(1.5)';
        setTimeout(function(){ cartBadge.style.transform = 'scale(1)'; }, 250);
    }

    setTimeout(function(){
        toast.style.transform = 'translateX(120%)';
        setTimeout(function(){ toast.remove(); }, 300);
    }, 2500);
}

/* ===== ปุ่ม "ซื้อเลย" — สินค้าไม่มีตัวเลือก (เหมือน .b-cart-one) แต่พาไปหน้าตะกร้าทันที ===== */
$(".b-buynow-one").click(function(){
    var e = $(this).data("id");
    var t = ($("#quantity").val() == null) ? 1 : $("#quantity").val();
    var n = ($("#ref").val() == null) ? "" : $("#ref").val();
    $.ajax({
        dataType: "json", method: "post", url: "/cart/add/one",
        data: { proId: e, quantity: t, ref: n },
        headers: { "X-CSRF-TOKEN": $('meta[name="csrf-token"]').attr("content") },
        cache: false,
        success: function(res){
            if (res.length != 0) { window.location.href = "/cart"; }
        },
        failure: function(e){ alert(e); }
    });
});

/* ===== ปุ่ม "ซื้อเลย" — สินค้ามีตัวเลือก (เหมือน .b-carttwo) แต่พาไปหน้าตะกร้าทันที ===== */
$(".b-buynow-two").click(function(){
    var e = $("#p_id").val();
    var t = $("#quantity").val();
    var n = (2 == $("#p_option").val()) ? $("#p_id_d").val() : $("#option_select").val();
    var a = ($("#ref").val() == null) ? "" : $("#ref").val();
    $.ajax({
        dataType: "json", method: "post", url: "/cart/add/two",
        data: { proId: e, detailId: n, quantity: t, ref: a },
        headers: { "X-CSRF-TOKEN": $('meta[name="csrf-token"]').attr("content") },
        cache: false,
        success: function(res){
            if (res.length != 0) { window.location.href = "/cart"; }
        },
        failure: function(e){ alert(e); }
    });
});